package doapp.juntos;
import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.net.Uri;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

public class SetupActivity extends Activity {
 final int BG=Color.rgb(250,248,245),INK=Color.rgb(42,38,53),MUTED=Color.rgb(130,123,142),PURPLE=Color.rgb(117,96,213),LILAC=Color.rgb(239,234,253);
 Store store;JSONObject draft;LinearLayout root,content;TextView status;int step;boolean busy;volatile boolean completed;Handler handler=new Handler(Looper.getMainLooper());ExecutorService worker=Executors.newSingleThreadExecutor();Runnable delayedSave=()->flush();
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);try{store=Store.get(this);draft=store.setupDraft();JSONObject cfg=store.config();if(draft.length()==0){for(String k:new String[]{"name","partner","token","chatA","chatB","secret","slot"})if(cfg.has(k))draft.put(k,cfg.get(k));}step=SetupRules.step(draft.optInt("step"));if(step==8)step=0;show();}catch(Exception e){new AlertDialog.Builder(this).setTitle("No se pudo abrir la guía").setMessage("Tu agenda sigue guardada. Vuelve a abrir Juntos para intentarlo otra vez.").setPositiveButton("Cerrar",(d,w)->finish()).show();}}
 @Override protected void onStop(){super.onStop();flush();}
 @Override protected void onDestroy(){super.onDestroy();handler.removeCallbacksAndMessages(null);worker.shutdown();}
 void flush(){if(store==null||draft==null||completed)return;try{synchronized(store){if(completed)return;store.setupDraft(draft);}}catch(Exception e){if(status!=null)status.setText("No se pudo guardar el progreso. Mantén esta pantalla abierta e inténtalo otra vez.");}}
 void save(String key,Object value){try{draft.put(key,value);handler.removeCallbacks(delayedSave);handler.postDelayed(delayedSave,400);}catch(Exception ignored){}}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 TextView text(String value,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setIncludeFontPadding(false);if(bold)t.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));return t;}
 void add(LinearLayout l,View v,int margin){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(margin);l.addView(v,p);}
 TextView button(String title,boolean main,Runnable action){TextView v=text(title,15,main?Color.WHITE:PURPLE,true);v.setGravity(Gravity.CENTER);v.setPadding(dp(14),dp(15),dp(14),dp(15));v.setMinHeight(dp(52));v.setBackground(bg(main?PURPLE:LILAC,17));v.setOnClickListener(w->{if(busy){toast("Espera a que termine la comprobación.");return;}action.run();});return v;}
 void paragraph(String value){TextView t=text(value,15,MUTED,false);t.setLineSpacing(dp(5),1);add(content,t,20);}
 void title(String icon,String heading,String copy){TextView image=text(icon,35,PURPLE,true);image.setPadding(0,dp(14),0,dp(18));add(content,image,4);add(content,text(heading,27,INK,true),13);paragraph(copy);}
 EditText input(String key,String hint,boolean secret){TextView label=text(hint,12,MUTED,true);add(content,label,8);EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(16);e.setTextColor(INK);e.setHintTextColor(MUTED);e.setHint(hint);e.setPadding(dp(15),dp(15),dp(15),dp(15));GradientDrawable b=bg(Color.WHITE,16);b.setStroke(dp(1),Color.rgb(235,230,239));e.setBackground(b);e.setInputType(android.text.InputType.TYPE_CLASS_TEXT|(secret?android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD:android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES));if(key.equals("token")||key.startsWith("chat"))e.setInputType(android.text.InputType.TYPE_CLASS_TEXT|(secret?android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD:android.text.InputType.TYPE_TEXT_VARIATION_URI));e.setText(draft.optString(key));e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){save(key,s.toString());}public void afterTextChanged(Editable s){}});add(content,e,16);return e;}
 void toggle(EditText input,String label){CheckBox show=new CheckBox(this);show.setText(label);show.setTextColor(MUTED);show.setButtonTintList(android.content.res.ColorStateList.valueOf(PURPLE));show.setOnCheckedChangeListener((b,checked)->{input.setTransformationMethod(checked?null:android.text.method.PasswordTransformationMethod.getInstance());input.setSelection(input.length());});add(content,show,16);}
 void check(String key,String label){CheckBox c=new CheckBox(this);c.setText(label);c.setTextColor(INK);c.setButtonTintList(android.content.res.ColorStateList.valueOf(PURPLE));c.setChecked(draft.optBoolean(key));c.setPadding(0,dp(10),0,dp(10));c.setOnCheckedChangeListener((b,checked)->save(key,checked));add(content,c,18);}
 void show(){root=col();root.setBackgroundColor(BG);root.setPadding(dp(24),0,dp(24),0);setContentView(root);if(Build.VERSION.SDK_INT>=30)root.setOnApplyWindowInsetsListener((v,i)->{Insets bars=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());root.setPadding(dp(24)+bars.left,bars.top,dp(24)+bars.right,bars.bottom);return i;});else root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(dp(24),i.getSystemWindowInsetTop(),dp(24),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();
  LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(0,dp(17),0,dp(17));TextView back=text(step==0?"Cerrar":"‹  Atrás",14,PURPLE,true);back.setPadding(0,dp(10),dp(10),dp(10));back.setOnClickListener(v->back());head.addView(back,new LinearLayout.LayoutParams(0,-2,1));head.addView(text("♥  Juntos",19,PURPLE,true));add(root,head,12);
  if(step>0){add(root,text("PASO "+step+" DE 8",11,MUTED,true),10);ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(8);progress.setProgress(step);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(PURPLE));add(root,progress,12);}
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=col();scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));render();status=text("",13,Color.rgb(173,52,64),false);status.setPadding(0,dp(8),0,dp(12));add(root,status,0);
  if(step>0&&step<8){add(root,button(step==2?"Comprobar bot y continuar":step==7?"Comprobar conexión":"Continuar",true,()->next()),8);add(root,button("Guardar y continuar luego",false,()->later()),12);}else if(step==8){add(root,button("Mostrar QR a mi pareja",true,()->done("qr")),9);add(root,button("Entrar a nuestra agenda",false,()->done("agenda")),14);}
 }
 void render(){switch(step){case 0:
  title("♥","Un espacio para ustedes","Vamos a preparar su agenda con pasos cortos. Solo una persona hace la configuración; su pareja se une con un QR.");
  add(content,button("Crear nuestra agenda",true,()->go(1)),12);add(content,button("Unirme a una agenda",false,()->{try{store.stateLong("setupSkipped",1);}catch(Exception ignored){}setResult(RESULT_OK,new Intent().putExtra("setupAction","join"));finish();}),16);
  if(draft.optInt("step")>0&&draft.optInt("step")<8)add(content,button("Continuar mi configuración",false,()->go(SetupRules.step(draft.optInt("step")))),12);
  add(content,button("Usar solo en este celular por ahora",false,()->later()),20);paragraph("Cada pareja utiliza su propio bot y sus dos canales privados de Telegram. La APK no incluye el token ni la agenda de quien te la compartió. La guía guarda el progreso en este celular.");break;
 case 1:title("✦","¿Cómo se llaman?","Estos nombres aparecerán al asignar actividades y recibir cambios de tu pareja.");input("name","Tu nombre",false);input("partner","Nombre de tu pareja",false);break;
 case 2:title("✉","Crea su bot","Abre el bot oficial @BotFather en Telegram, envía /newbot y sigue sus instrucciones. Al terminar te entregará un token: cópialo y pégalo aquí.");add(content,button("Abrir BotFather en Telegram",false,()->open("https://t.me/BotFather")),12);add(content,button("Copiar el comando /newbot",false,()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Crear bot","/newbot"));toast("Comando copiado");}),18);EditText token=input("token","Token entregado por BotFather",true);toggle(token,"Mostrar token");paragraph("No compartas el token con otras parejas. Si ya creaste un bot exclusivo para esta agenda, puedes usar ese mismo. Antes de avanzar comprobaremos que responde.");break;
 case 3:channelStep("A");break;
 case 4:channelStep("B");break;
 case 5:title("⌁","Conecta los dos canales","Después de añadir el bot, publica una palabra nueva en cada canal. Pulsa Detectar y elige primero A y después B.");add(content,button("Detectar mis canales",false,()->detect()),18);input("chatA","Canal A: ID o enlace de un mensaje",false);input("chatB","Canal B: ID o enlace de un mensaje",false);paragraph("Si no aparecen: en Telegram, mantén pulsado un mensaje del canal y usa Copiar enlace. Pega ese enlace aquí; Juntos obtiene el ID. Debe verse como t.me/c/… . El enlace para invitar personas no sirve.");break;
 case 6:title("🔐","Protege sus copias","Elige una frase de al menos 12 caracteres para cifrar su agenda. Guárdala en un lugar seguro: la necesitarás si recuperas una copia exportada.");EditText secret=input("secret","Clave compartida de la agenda",true);toggle(secret,"Mostrar clave");paragraph("Tu pareja no tendrá que escribirla: se transfiere al vincular con el QR. Quien tenga ese QR completo podrá acceder a su agenda, así que muéstralo solo a tu pareja.");break;
 case 7:title("✓","Comprobemos que todo está listo","Vamos a comprobar el bot, el acceso a ambos canales, sus permisos para publicar y editar, y el guardado de la agenda. Necesitas internet.");summary("Sus nombres",draft.optString("name")+" y "+draft.optString("partner"));summary("Bot",draft.optString("botUsername").isEmpty()?"Token guardado en este celular":"@"+draft.optString("botUsername"));summary("Canal A",draft.optString("chatA"));summary("Canal B",draft.optString("chatB"));paragraph("Todavía puedes volver y corregir cualquier dato. Si falla una comprobación, verás qué debes revisar; no se dará la conexión por terminada.");break;
 case 8:title("♥","Su agenda está lista","Ya comprobamos la conexión y guardamos la agenda. Muestra el QR a tu pareja para que se una sin copiar tokens ni elegir canales.");String slot="A";try{slot=store.config().optString("slot","A");}catch(Exception ignored){}summary("Este celular", "Espacio "+slot);summary("Celular de tu pareja", "Espacio "+LinkRules.opposite(slot));paragraph("Cuando se vincule se descargarán también las actividades completadas y se abrirá Todas. Podrán comenzar a registrar sus planes.");break;
 }}
 void channelStep(String label){title("▦","Prepara el canal "+label,"En Telegram, crea un canal nuevo y elige Privado. Puedes llamarlo Juntos "+label+". Cada canal es un espacio de guardado; ambos celulares verán la misma agenda.");String username=draft.optString("botUsername");summary("1 · Canal privado","Crea Juntos "+label+" y confirma que su tipo sea Privado.");summary("2 · Añade tu bot","Abre los administradores del canal y añade "+(username.isEmpty()?"el bot que acabas de crear":"@"+username)+". No añadas a @BotFather.");summary("3 · Permisos","Permítele publicar y editar mensajes.");summary("4 · Mensaje nuevo","Publica «Hola» después de añadir el bot.");add(content,button("Abrir Telegram",false,()->open("https://t.me/")),15);check("channel"+label+"Ready","Ya creé el canal "+label+" y añadí mi bot como administrador");}
 void summary(String label,String value){LinearLayout card=col();card.setPadding(dp(16),dp(15),dp(16),dp(15));card.setBackground(bg(LILAC,18));add(card,text(label,12,PURPLE,true),7);card.addView(text(value,15,INK,false));add(content,card,12);}
 void go(int target){if(busy)return;step=SetupRules.step(target);save("step",step);save("active",step>0&&step<8);try{store.stateLong("setupSkipped",0);}catch(Exception ignored){}flush();show();}
 void next(){try{switch(step){case 1:if(draft.optString("name").trim().isEmpty()||draft.optString("partner").trim().isEmpty()){error("Escribe los dos nombres para continuar.");return;}if(draft.optString("name").length()>40||draft.optString("partner").length()>40){error("Usa nombres de hasta 40 caracteres.");return;}save("name",draft.optString("name").trim());save("partner",draft.optString("partner").trim());go(2);break;
 case 2:if(!SetupRules.tokenValid(draft.optString("token"))){error("Pega el token completo, con los números, los dos puntos y las letras.");return;}save("token",draft.optString("token").trim());run("Comprobando el bot…",()->{JSONObject bot=new TelegramSetup(store,draft.getString("token")).bot();return bot;},value->{save("botUsername",value.optString("username"));go(3);});break;
 case 3:case 4:String letter=step==3?"A":"B";if(!draft.optBoolean("channel"+letter+"Ready")){error("Marca la casilla cuando hayas creado el canal y añadido el bot.");return;}go(step+1);break;
 case 5:String a=SetupRules.channelId(draft.optString("chatA")),b=SetupRules.channelId(draft.optString("chatB"));if(a.equals(b)){error("A y B deben ser canales diferentes.");return;}save("chatA",a);save("chatB",b);go(6);break;
 case 6:if(draft.optString("secret").length()<12){error("La clave necesita al menos 12 caracteres. Puede ser una frase.");return;}if(draft.optString("secret").length()>256){error("Usa una clave de hasta 256 caracteres para que quepa en el QR.");return;}go(7);break;
 case 7:verify();break;default:go(step+1);}}catch(Exception e){error(e.getMessage()==null?"Revisa este paso.":e.getMessage());}}
 interface Work {JSONObject call()throws Exception;}interface Success {void accept(JSONObject value)throws Exception;}
 void run(String message,Work work,Success success){if(busy)return;busy=true;status.setTextColor(PURPLE);status.setText(message);flush();worker.execute(()->{try{JSONObject result=work.call();handler.post(()->{busy=false;if(isFinishing()||isDestroyed())return;try{success.accept(result);}catch(Exception e){error("No se pudo completar este paso. Tu progreso está guardado.");}});}catch(Exception e){String messageError=(e instanceof TelegramSetup.SetupError||e instanceof TelegramSync.SyncError)?e.getMessage():"No se pudo conectar con Telegram. Revisa internet y vuelve a intentarlo; tu progreso está guardado.";handler.post(()->{busy=false;if(!isFinishing()&&!isDestroyed())error(messageError);});}});}
 void verify(){final JSONObject values;try{values=new JSONObject(draft.toString());}catch(Exception e){error("No se pudieron leer los datos.");return;}run("Comprobando canales y guardando la agenda…",()->{new TelegramSetup(store,values.getString("token")).validate(values.getString("chatA"),values.getString("chatB"));synchronized(TelegramSync.SYNC_LOCK){JSONObject cfg=store.config();for(String key:new String[]{"name","partner","token","chatA","chatB","secret"})cfg.put(key,values.getString(key));if(!cfg.optString("slot").equals("A")&&!cfg.optString("slot").equals("B"))cfg.put("slot","A");store.config(cfg);String state=new TelegramSync(store).sync();synchronized(store){store.setupComplete();completed=true;}return new JSONObject().put("state",state);}},value->{completed=true;step=8;handler.removeCallbacks(delayedSave);show();Alerts.refresh(this);});}
 void detect(){run("Buscando canales recientes…",()->{LinkedHashMap<String,String> channels=new TelegramSetup(store,draft.getString("token")).channels();JSONObject out=new JSONObject();for(Map.Entry<String,String> entry:channels.entrySet())out.put(entry.getKey(),entry.getValue());return out;},found->{if(found.length()==0){error("Todavía no aparecen. Publica otro mensaje en cada canal después de añadir el bot y reintenta, o pega los enlaces de los mensajes.");return;}List<String> ids=new ArrayList<>();Iterator<String> keys=found.keys();while(keys.hasNext())ids.add(keys.next());pickChannel("A",ids,found);});}
 void pickChannel(String label,List<String> all,JSONObject found){List<String> ids=new ArrayList<>();for(String id:all)if(label.equals("A")||!id.equals(draft.optString("chatA")))ids.add(id);if(ids.isEmpty()){show();error("Encontramos el canal A. Publica un mensaje en el B y vuelve a detectar, o pega su enlace.");return;}String[] names=new String[ids.size()];for(int j=0;j<ids.size();j++)names[j]=found.optString(ids.get(j))+"\n"+ids.get(j);new AlertDialog.Builder(this).setTitle("Elige el canal "+label).setItems(names,(d,w)->{save("chat"+label,ids.get(w));flush();if(label.equals("A"))pickChannel("B",all,found);else{show();status.setTextColor(PURPLE);status.setText("Los dos canales están seleccionados.");}}).setNegativeButton("Cancelar",null).show();}
 void error(String value){status.setTextColor(Color.rgb(173,52,64));status.setText(value);}
 void open(String url){flush();try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){toast("Abre Telegram manualmente y sigue las instrucciones de este paso.");}}
 void later(){if(busy)return;flush();try{store.stateLong("setupSkipped",1);}catch(Exception ignored){}finish();}
 void done(String action){setResult(RESULT_OK,new Intent().putExtra("setupAction",action));finish();}
 void back(){if(busy){toast("Espera a que termine la comprobación.");return;}if(completed||step==8){done("agenda");return;}if(step<=0)later();else go(step-1);}
 @Override public void onBackPressed(){back();}
 void toast(String value){Toast.makeText(this,value,Toast.LENGTH_LONG).show();}
}
